气泡宽度默认360px，觉得太宽或太窄的可以自己调
标注🎶的是自定义文字区域*/
/* 二改-沉溺@z. 
用到其他老師分享的代碼已有標註~
新增了思維鏈自定義、滾動&世界書、收藏角色的顏色&底部切換箭頭
搜尋🎸可改自定義內容 */

/* ============================================================
   消息卡片 - Message Card (日間暖白)
   ============================================================ */
body.bubblechat .mes,
body.bubblechat .mes[is_user="true"],
.mes {
    padding: 240px 15px 30px !important;
    border-radius: 0px !important;
    border: 1px solid #8a1d1d !important; /* 暗紅邊框 */
    box-shadow: 8px 8px 20px rgba(138, 29, 29, 0.1), inset 0 0 0 1px rgba(166, 36, 36, 0.05) !important; /* 柔和的紅色陰影 */
    max-width: 420px !important;
    margin: 40px auto 20px !important;
    position: relative;
    background-color: #fcf9f9 !important; /* 暖調白 */
    background-image: linear-gradient(180deg, #ffffff 0, #fcf9f9 100%) !important;
    box-sizing: border-box !important;
    overflow: visible !important;
}

.mes_block {
    width: 100% !important;
    max-width: 100% !important;
    padding: 0 !important;
    margin: 0 !important;
}

.mes_text {
    padding: 0 !important;
    margin: 0 !important;
    text-align: left !important;
    color: #2c2424 !important; /* 深灰偏黑，適合日間閱讀 */
    line-height: 1.5 !important;
    font-weight: 400 !important;
    text-rendering: optimizeLegibility !important;
}

/* ============================================================
   UI 排版 - UI Layout
   ============================================================ */

* {
    border-radius: 0 !important;
}

.drawer-content .range-block,
.inline-drawer-header h4,
.standoutHeader,
h4,
h4[data-i18n] {
    border: none !important;
    background: 0 0 !important;
    box-shadow: none !important;
    color: #8b0000 !important; /* 標題暗紅 */
    text-shadow: none !important;
    border-radius: 0 !important;
    margin-bottom: 5px !important;
    border-bottom: 1px dashed #d4baba !important; /* 淺紅虛線 */
    padding-bottom: 5px !important;
}

/* ============================================================
   扩展列表 - Extension List
   ============================================================ */

.inline-drawer-toggle,
.list-group-item,
.drawer-content .list-group-item,
#extensions_menu .inline-drawer-toggle {
    background: #ffffff !important; 
    background-image: none !important;
    border: 1px solid #e6dcdc !important;
    color: #4a3535 !important;
    box-shadow: none !important;
    text-shadow: none !important;
    border-radius: 0 !important;
    margin-bottom: 6px !important;
    transition: all .3s ease;
}

.inline-drawer-toggle:hover,
.list-group-item:hover {
    background: #f5ebeb !important;
    color: #8a1d1d !important;
    border-color: #d4baba !important; 
}

.inline-drawer-toggle i,
.inline-drawer-toggle .fa-chevron-down,
.inline-drawer-toggle .fa-chevron-right,
.inline-drawer-icon {
    color: #8a1d1d !important;
    text-shadow: none !important;
}

/* ============================================================
   控件扁平化 - Flat Controls
   ============================================================ */

.text_pole,
textarea,
select,
.menu_button,
.character_select,
.group_select,
input[type="text"],
input[type="number"] {
    background-color: #ffffff !important;
    border: 1px solid #d4baba !important;
    color: #2c2424 !important;
    border-radius: 0 !important;
    box-shadow: none !important;
    transition: all .3s ease;
}

.menu_button {
    background-color: #fcf9f9 !important;
}

.text_pole:focus,
textarea:focus,
select:focus {
    border-color: #8a1d1d !important;
    background-color: #ffffff !important;
    box-shadow: 0 0 10px rgba(138, 29, 29, .1) !important;
    outline: 0 !important;
}

.menu_button:hover {
    background-color: #f5ebeb !important;
    color: #8a1d1d !important;
    border-color: #8a1d1d !important;
}

#completion_prompt_manager_list {
    background-color: transparent !important;
    border: none !important;
}

#completion_prompt_manager_list .completion_prompt_manager_prompt_name.text_muted,
#completion_prompt_manager_list .completion_prompt_manager_prompt_name *,
#completion_prompt_manager_list .text_muted,
.completion_prompt_manager_prompt_name {
    color: #8a5c5c !important;
    opacity: 1 !important;
    -webkit-text-fill-color: #8a5c5c !important;
    text-shadow: none !important;
}

/* ============================================================
   滑块
   ============================================================ */

input[type="range"] {
    -webkit-appearance: none !important;
    appearance: none !important;
    background: linear-gradient(#8a1d1d, #8a1d1d) center / 100% 1px no-repeat !important; 
    height: 28px !important;
    border: 0 !important;
    box-shadow: none !important;
    outline: 0 !important;
    mix-blend-mode: normal !important;
    opacity: 1 !important;
    cursor: pointer;
    overflow: visible !important;
}

input[type="range"]::-webkit-slider-thumb {
    -webkit-appearance: none !important;
    width: 38px !important;
    height: 26px !important;
    background: url('https://i.ibb.co/H960nkg/894-A8-ACD-9447-427-D-B756-46454-B4-D5858.png') center / contain no-repeat !important;
    border: 0 !important;
    border-radius: 0 !important;
    filter: invert(1) hue-rotate(180deg) brightness(0.8); /* 日間模式翻轉圖標顏色 */
  background-color: transparent !important;
  box-shadow: none !important;
}

input[type="range"]::-moz-range-thumb {
    width: 38px !important;
    height: 26px !important;
    background: url('https://i.ibb.co/GfV3ZmpM/E8625-C1-F-ACFA-4660-B14-D-CFFF18620-A8-C.png') center / contain no-repeat !important;
    border: 0 !important;
    border-radius: 0 !important;
    filter: invert(1) hue-rotate(180deg) brightness(0.8);
}

/* ============================================================
   复选框 - Checkbox
   ============================================================ */

input[type="checkbox"] {
    border-radius: 0 !important;
    -webkit-appearance: none;
    appearance: none;
    background: 0 0 !important;
    border: 1px solid #d4baba !important;
    width: 16px;
    height: 16px;
    position: relative;
    vertical-align: middle;
    cursor: pointer;
    outline: 0 !important;
}

input[type="checkbox"]:checked {
    border-color: #8a1d1d !important;
    background: 0 0 !important;
}

input[type="checkbox"]::before {
    content: none !important;
}

input[type="checkbox"]:checked::after {
    content: '' !important;
    position: absolute;
    left: 50%;
    top: 50%;
    transform: translate(-50%, -50%) !important;
    width: 14px;
    height: 14px;
    background: url('https://files.catbox.moe/w4sj3e.jpg') center / cover no-repeat !important;
    /* 日間模式稍微調亮紅暈 */
    filter: grayscale(0.2) brightness(1.1) sepia(0.5) hue-rotate(320deg) !important; 
}

::-webkit-scrollbar {
    display: none;
}

/* ============================================================
   顶栏图标 - Top Bar Icons
   ============================================================ */

#top-bar {
    margin: 0 auto;
    left: 0;
    right: 0;
    display: inline-block;
    height: 24px;
    position: absolute;
    box-shadow: none;
    opacity: 0;
    z-index: 3005;
}

.drawer-icon {
    transform: scale(.55);
    color: #8a5c5c;
}

/* ============================================================
   输入栏 - Input Bar
   ============================================================ */

#send_form {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    width: 98% !important;
    max-width: 850px;
    margin: 0px auto !important;
    background: #ffffff !important;
    border: 1px solid #8a1d1d !important; 
    border-radius: 0 !important;
    box-shadow: 0 10px 30px rgba(138, 29, 29, 0.15) !important;
}

#nonQRFormItems {
    padding: 4px 12px !important;
    position: relative;
    display: flex;
    flex-direction: row;
    column-gap: 5px;
    order: 25;
    width: 100%;
    min-height: 40px !important;
    align-items: center;
    overflow: hidden;
    background-color: #ffffff !important;
    border: none !important;
    box-shadow: none !important;
    z-index: 50;
}

.qr--buttons {
    opacity: 0;
    visibility: hidden;
    max-height: 0;
    margin: 0 !important;
    padding: 0 !important;
    transform: translateY(15px);
    transition: all .3s cubic-bezier(.2, 1, .3, 1);
    overflow: hidden;
}

#send_form:focus-within .qr--buttons {
    opacity: 1;
    visibility: visible;
    max-height: 300px;
    margin-bottom: 8px !important;
    transform: translateY(0);
    pointer-events: auto;
}

#rightSendForm > div:not(.mes_stop),
#leftSendForm > div {
    transform: scale(.6) !important;
    color: #8b0000; 
}

/* 输入渐变 */
#send_textarea {
    background: 0 0 !important;
    border: 0 !important;
    box-shadow: none !important;
    color: #2c2424 !important; /* 日間輸入字體深灰 */
}

#send_textarea::placeholder,
#send_textarea::-webkit-input-placeholder {
    color: transparent !important;
    opacity: 0 !important;
    -webkit-text-fill-color: transparent !important;
}

#nonQRFormItems:has(#send_textarea:placeholder-shown)::before {
    content: "「副歌，跟著唱」" !important; /* 🎸 */
    position: absolute !important;
    top: 50% !important;
    left: 50% !important;
    transform: translate(-50%, -50%) !important;
    font-style: italic !important;
    font-size: 12px !important;
    pointer-events: none !important;
    z-index: 10 !important;
    white-space: nowrap !important;
    color: #d4baba !important; /* 日間浮水印淺紅 */
    letter-spacing: 1px !important;
}

/* ============================================================
   思维链
   ============================================================ */

.mes_reasoning_details {
    width: 100% !important;
    margin: 10px 0 !important;
    border: 0 !important;
    background: 0 0 !important;
    overflow: visible !important;
}

.mes_reasoning_header,
.mes_reasoning_summary,
.mes_reasoning_header_text {
    background: #ffffff !important;
    background-image: none !important;
    box-shadow: none !important;
    border-radius: 0 !important;
}

.mes_reasoning_summary {
    width: 100% !important;
    box-sizing: border-box !important;
    border: 1px solid #e6dcdc !important;
    border-left: 4px solid #8a1d1d !important; 
    padding: 5px 15px !important;
    color: #5c4d4d !important;
    position: relative !important;
    display: flex !important;
    align-items: center !important;
    min-height: 32px !important;
    cursor: pointer !important;
    box-shadow: 3px 3px 0 rgba(138, 29, 29, 0.05) !important;
    justify-content: flex-start !important;
    font-size: 12px !important;
    letter-spacing: 1px !important;
}

.mes_reasoning_summary::after {
    content: '' !important;
    position: absolute;
    left: 8px;
    top: 50%;
    transform: translateY(-50%) !important;
    width: 20px;
    height: 14px;
    background: url('https://i.ibb.co/bjMTq7kM/AE0-F6-D01-23-B7-4-A6-B-952-A-D3-C1-FB181-E66.png') center / contain no-repeat !important;
    filter: opacity(0.7) !important; 
}

.mes_reasoning {
    width: 100% !important;
    box-sizing: border-box !important;
    background: #fcf9f9 !important;
    border: 1px dashed #d4baba !important;
    border-top: 0 !important;
    color: #6a5353 !important;
    font-size: .85em !important;
    line-height: 1.7 !important;
    padding: 15px !important;
    margin: 0 !important;
    max-height: 350px; /* 思維鏈滾動@Serein */
    overflow: hidden auto; /* 思維鏈滾動@Serein */
}

.mes_reasoning_header_icon,
.mes_reasoning_details summary::marker {
    position: absolute !important;
    right: 10px !important;
    top: 50%;
    transform: translateY(-50%) !important;
    color: #8b0000 !important;
}

/* ============================================================
   正文修饰
   ============================================================ */

.mes_text strong {
    position: relative !important;
    color: #8a1d1d !important; /* 日間加粗改為暗紅 */
    font-weight: 700 !important;
    letter-spacing: 0.15em !important;
    text-shadow: none !important; /* 移除文字陰影，日間更乾淨 */
    padding: 0 4px !important;
    border-bottom: 1px solid rgba(138, 29, 29, 0.3) !important; 
    margin: 0 2px !important;
}

.mes_text em {
    position: relative !important;
    padding-left: 18px !important;
    font-style: italic !important;
    color: #a55c5c !important; /* 斜體字淺暗紅 */
    display: inline-block !important;
    letter-spacing: 1px !important;
}

.mes_text em::before {
    content: '' !important;
    position: absolute !important;
    left: 0;
    top: 50%;
    transform: translateY(-50%) !important;
    width: 14px;
    height: 40px;
    background: url('https://i.ibb.co/s9H6GChQ/425-BF1-BF-1-D5-D-48-B5-8-A8-D-97-EDD51193-CB.png') center / contain no-repeat !important;
    filter: opacity(0.8) !important;
}

pre code,
pre span {
    background: 0 0 !important;
    color: inherit !important;
    text-shadow: none !important;
}

/* ============================================================
   代码块 - Code Block
   ============================================================ */

pre {
    background: #ffffff !important;
    color: #2c2424 !important;
    border: 1px solid #d4baba !important;
    box-shadow: 5px 5px 0 #f5ebeb, 10px 10px 0 #ece1e1 !important; /* 陰影改為淺色漸層 */
    margin: 0 !important;
    padding: 40px 15px 15px !important;
    position: relative !important;
}

pre::before {
    content: '𝑌𝑜𝑢 𝑎𝑟𝑒 𝑚𝑦 𝑘𝑒𝑦𝑤𝑜𝑟𝑑.' !important; /* 🎸  */ 
    position: absolute;
    top: -1px;
    left: -1px;
    background: #8a1d1d !important; /* 背景暗紅 */
    color: #ffffff !important;
    padding: 6px 15px 6px 35px !important;
    font-weight: 900 !important;
    font-size: .7em !important;
    box-shadow: 2px 2px 0 rgba(138, 29, 29, .2) !important;
}

pre::after {
    content: '' !important;
    position: absolute;
    top: 6px;
    left: 10px;
    width: 15px;
    height: 14px;
    background: url('https://i.ibb.co/bjMTq7kM/AE0-F6-D01-23-B7-4-A6-B-952-A-D3-C1-FB181-E66.png') center / contain no-repeat !important;
    filter: brightness(0) invert(1) !important;
    z-index: 10;
}

/* ============================================================
   对话引用 - Quote / Dialog
   ============================================================ */

q {
    color: #8b0000 !important;
    background: 0 0 !important;
    border: 0 !important;
    padding: 0 15px !important;
    font-style: normal !important;
    font-weight: 600 !important;
    position: relative;
    display: inline-block;
    letter-spacing: 0.5px;
}

q::before {
    content: '「' !important;
    position: absolute;
    left: -5px;
    top: -5px;
    font-size: 1.5em;
    color: rgba(138, 29, 29, .4); 
}

q::after {
    content: '」' !important;
    position: absolute;
    right: -5px;
    bottom: -5px;
    font-size: 1.5em;
    color: rgba(138, 29, 29, .4); 
}

:not(pre) > code {
    background: #f5ebeb !important;
    color: #8a1d1d !important;
    padding: 2px 10px !important;
    border: 1px solid #d4baba !important;
    box-shadow: 2px 2px 0 #e6dcdc, 4px 4px 0 #d4baba !important;
    margin: 0 4px !important;
    letter-spacing: .15em !important;
    display: inline-block !important;
    line-height: 1.4 !important;
    text-shadow: none !important;
    vertical-align: middle;
}

/* ============================================================
   引用块 - Blockquote
   ============================================================ */

blockquote {
    margin: 30px 0 !important;
    padding: 20px !important;
    border: 1px solid #d4baba !important;
    background: #ffffff !important;
    box-shadow: 4px 4px 0 #f5ebeb, 8px 8px 0 #ece1e1 !important;
    color: #5c4d4d !important;
    position: relative !important;
    display: block !important;
    font-style: italic !important;
    letter-spacing: .05em !important;
}

blockquote::after {
    content: '𝐵𝑎𝑠𝑠 𝑑𝑒𝑒𝑝, 𝑠𝑜𝑢𝑙 𝑓𝑟𝑒𝑒.' !important; /* 🎸  */
    position: absolute;
    top: -11px;
    right: 15px;
    background: #8a1d1d !important; 
    color: #ffffff !important;
    padding: 2px 8px !important;
    font-size: .7em !important;
    font-weight: 900 !important;
    box-shadow: 2px 2px 0 rgba(138, 29, 29, .2) !important;
}

/* ============================================================
   封面
   ============================================================ */

.mesAvatarWrapper {
    width: calc(100% - 20px) !important;
    height: 220px !important;
    position: absolute !important;
    left: 10px !important;
    top: 10px !important;
    z-index: 5 !important;
    background: #ffffff url('https://i.ibb.co/JFS9TLtQ/2-E519-CAD-25-B4-4007-AACF-3-C4-BE93-C6-C1-F.jpg') left / 70% auto no-repeat !important;
    overflow: hidden !important;
    border: 1px solid #e6dcdc !important;
    box-shadow: inset 0 0 50px rgba(255, 255, 255, .8) !important; /* 邊緣泛白 */
}

.mesAvatarWrapper .avatar {
    width: 70% !important;
    height: 100% !important;
    position: absolute !important;
    right: 0 !important;
    top: 0 !important;
    /* 日間模式的漸變遮罩改為融入白色 */
    -webkit-mask-image: linear-gradient(to right, transparent 0, white 40%, white 100%) !important;
    mask-image: linear-gradient(to right, transparent 0, white 40%, white 100%) !important;
}

.mesAvatarWrapper .avatar img {
    width: 100% !important;
    height: 100% !important;
    object-fit: cover !important;
    filter: brightness(1.05) !important;
    object-position: center 25% !important;
}

.mesAvatarWrapper::before {
    content: "SILENT ARCHIVE / FALLING SNOW..." !important; /* 🎸 */
    position: absolute !important;
    left: 10px !important;
    top: 50% !important;
    transform: rotate(-90deg) translateY(-50%) !important;
    transform-origin: left center !important;
    font-size: 8px !important;
    color: rgba(138, 29, 29, .4) !important;
    letter-spacing: 3px !important;
    white-space: nowrap !important;
    z-index: 10;
    text-shadow: 0 0 2px rgba(255, 255, 255, .8) !important;
}

.mesAvatarWrapper::after {
    content: "" !important;
    position: absolute !important;
    right: 10px !important;
    top: 10px !important;
    width: 45px !important;
    height: 45px !important;
    z-index: 10 !important;
    background: url('https://i.ibb.co/ymKKPbht/24994146-78-D4-4-C1-A-B402-20-EF05-C6-FCDE.png') center / contain no-repeat !important;
    border: none !important;
    filter: opacity(0.95) !important; /* 日間模式圖標反轉變淡 */
}

.mes .name_text {
    font-size: 1.8em !important;
    font-weight: 700 !important;
    position: absolute !important;
    left: 25px !important;
    top: 140px !important;
    text-align: left !important;
    color: #8b0000 !important; /* 名字暗紅 */
    letter-spacing: 2px !important;
    z-index: 20;
    text-shadow: 1px 1px 0px rgba(255, 255, 255, 0.8) !important; /* 淺色外發光確保能看清 */
    width: calc(100% - 60px) !important;
    word-wrap: break-word !important;
}

.mes .name_text::after {
    content: "當世界沒有意義 我會戴上有你聲音的耳機" !important; /* 🎸 */
    display: block !important;
    font-size: 12px !important;
    font-weight: 900 !important;
    letter-spacing: 1px !important;
    margin-top: 8px !important;
    color: #5c4d4d !important; 
    text-transform: none !important;
    text-shadow: 1px 1px 2px rgba(255,255,255,0.8) !important;
    font-style: italic !important;
    white-space: normal !important;
    line-height: 1.3 !important;
}

.mes .mes_timer,
.mes .mesIDDisplay,
.mes .tokenCounterDisplay {
    background: transparent !important;
    color: #8a5c5c !important;
    top: 200px !important;
    font-size: 10px !important;
  -webkit-text-stroke: 0.1px white;
  font-weight: 700;
}

.mes .timestamp {
    top: 240px !important;
    font-style: italic;
    border-top: 1px solid #e6dcdc;
    padding-top: 8px;
    width: 100%;
    color: #a58a8a !important;
}

/* ============================================================
   弹窗 Toast
   ============================================================ */

#toast-container > .toast {
    color: #2c2424 !important;
    background: rgba(255, 255, 255, .95) !important; /* 日間白底毛玻璃 */
    backdrop-filter: blur(5px) !important;
    border: 1px solid #8a1d1d !important;
    outline: 0 !important;
    box-shadow: 0 10px 30px rgba(138, 29, 29, .15) !important;
    padding: 15px 5px 15px 45px !important;
    border-radius: 0px !important;
}

#toast-container > .toast::before {
    content: '' !important;
    position: absolute !important;
    left: 13px !important;
    top: 50% !important;
    transform: translateY(-50%) !important;
    width: 26px !important;
    height: 26px !important;
    background: url('https://i.ibb.co/GfV3ZmpM/E8625-C1-F-ACFA-4660-B14-D-CFFF18620-A8-C.png') center / contain no-repeat !important;
    filter: invert(1) hue-rotate(180deg) brightness(0.5) !important;
}

#toast-container > .toast-error::before,
#toast-container > .toast-warning::before {
    background: url('https://files.catbox.moe/w4sj3e.jpg') center / contain no-repeat !important;
    left: 14px !important;
}

/* ============================================================
    新增

============================================================ */

/* @Serein */
#send_textarea {
  resize: none;
}

/* 世界書顏色 */
.world_set, 
.toggleEnabled {
    color: #8b0000 !important; 
}
/* 角色收藏顏色 */
.fav_on {
    color: #8b0000 !important; 
}

.mes_buttons, .extraMesButtons{
  font-size: calc(var(--mainFontSize) * 0.9) !important;
}

/* 切換鈕 */
.last_mes {
  .swipe_right::before,
  .swipe_left::before {
    content: "♪"; /* 🎸 */
    font-size: 0.75em;
    color: #8a1d1d; 
    -webkit-text-stroke: 0px white;
  }

  .swipeRightBlock {
    display: flex;
    flex-direction: row-reverse;
    width: 100%;
    padding-right: 20px;
    margin-bottom: 0.3rem;
  }

  .swipe_left {
    display: flex;
    transform: translateY(calc(var(--swipeCounterHeight, 0px) + var(--swipeCounterMargin, 0px)));
    margin-bottom: 0.3rem;
  }

  .swipes-counter {
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    font-size: 0.65em !important;
    color: #8a5c5c;
  }
}

